const cfg = $('Config').first().json;
// An unknown ID is kept (the name says so) so that a typo is visible in the sheet.
const names = new Map($input.all().map(i => i.json).filter(r => r.room_id).map(r => [String(r.room_id), r.name]));
const ids = String(cfg.room_ids ?? '').split(/[\s,]+/).filter(Boolean);
return ids.map(id => ({ json: { room_id: id, room_name: names.get(id) ?? '(unknown room)' } }));

const cfg = $('Config').first().json;
const keyword = String(cfg.keyword ?? '').trim();
const marker = String(cfg.reply_marker ?? '').trim();
const maxAge = Number(cfg.max_age_hours) || 0;
const nowSec = Math.floor(Date.now() / 1000);
const tz = cfg.timezone || 'Asia/Tokyo';

// Chatwork writes mentions, replies, quotes and blocks as [tags]. Turn them into plain text and keep what is useful.
function toPlain(body) {
  const mentions = [];
  let replyTo = '';
  let s = body;
  s = s.replace(/\[To:(\d+)\]\s*/g, (_, id) => { mentions.push(id); return '@'; });
  s = s.replace(/\[rp aid=(\d+) to=([\d-]+)\]\s*/g, (_, aid, to) => { replyTo = to; return '(reply) '; });
  s = s.replace(/\[qt\]\[qtmeta[^\]]*\]([\s\S]*?)\[\/qt\]\s*/g, (_, q) => q.trim().split('\n').map(l => '> ' + l).join('\n') + '\n');
  s = s.replace(/\[title\]([\s\S]*?)\[\/title\]/g, '[$1] ');
  s = s.replace(/\[\/?(?:info|code|hr)\]/g, '');
  s = s.replace(/\[\/?[a-z]+(?:[: ][^\]]*)?\]/g, '');
  return { text: s.trim(), mentions, replyTo };
}

const out = [];
for (const it of $input.all()) {
  const m = it.json;
  if (!m.message_id || typeof m.body !== 'string') continue; // an error item or an empty room
  // system messages (room created, task added...) look like [info][title][dtext:...]
  if (!cfg.include_system && /\[dtext:/.test(m.body)) continue;
  // our own confirmations carry the marker; they are not notes
  if (marker && m.body.includes(marker)) continue;
  if (maxAge && nowSec - Number(m.send_time) > maxAge * 3600) continue;
  const p = toPlain(m.body);
  const isNote = !!keyword && m.body.includes(keyword);
  const text = isNote && cfg.strip_keyword ? p.text.split(keyword).join('').trim() : p.text;
  const sentAt = DateTime.fromSeconds(Number(m.send_time), { zone: tz }).toFormat('yyyy-MM-dd HH:mm:ss');
  out.push({ json: {
    message_id: String(m.message_id),
    room_id: String(m.room_id),
    room_name: m.room_name,
    sent_at: sentAt,
    sent_date: sentAt.slice(0, 10),
    sender_id: String(m.account?.account_id ?? ''),
    sender_name: m.account?.name ?? '',
    text,
    mentions: p.mentions.join(','),
    reply_to: p.replyTo,
    edited: Number(m.update_time) > 0,
    raw: m.body,
    is_note: isNote,
  } });
}
return out;

// Notes that already have a row in the records tab are not read by the AI again (and get no second reply),
// even when the "already seen" history is gone because the workflow was imported again.
const recorded = new Set($input.all().map(i => String(i.json.message_id ?? '')).filter(Boolean));
return $('Is it an accounting note?').all().filter(i => !recorded.has(String(i.json.message_id)));

// ---- guard for AI-extracted accounting notes -------------------------------------------------
const nfkc = (s) => String(s ?? '').normalize('NFKC');
const squash = (s) => nfkc(s).replace(/\s+/g, '');

// "3万5千" -> 35000, "1.5万" -> 15000, "3200" -> 3200
function parseYen(str) {
  let total = 0;
  const man = str.match(/(\d+(?:\.\d+)?)万/);
  const sen = str.match(/(\d+(?:\.\d+)?)千/);
  if (man) total += Number(man[1]) * 10000;
  if (sen) total += Number(sen[1]) * 1000;
  const rest = str.replace(/(\d+(?:\.\d+)?)[万千]/g, '').match(/\d+(?:\.\d+)?/);
  if (rest) total += Number(rest[0]);
  return Math.round(total);
}

// Every amount that is really written in the message (numbers next to 円 / yen / ¥). If none is marked, fall back to bare numbers.
function amountCandidates(text) {
  const t = nfkc(text).replace(/(?<=\d),(?=\d{3}(?!\d))/g, '');
  const token = '((?:\\d+(?:\\.\\d+)?[万千])*(?:\\d+(?:\\.\\d+)?)?)';
  const found = [];
  for (const re of [new RegExp('[¥￥]\\s*' + token, 'g'), new RegExp(token + '\\s*(?:円|yen|JPY|えん)', 'gi')]) {
    for (const m of t.matchAll(re)) if (m[1] && /\d/.test(m[1])) found.push(parseYen(m[1]));
  }
  if (found.length) return { values: [...new Set(found)], marked: true };
  const bare = (t.match(/\d+(?:\.\d+)?/g) ?? []).map(Number);
  return { values: [...new Set(bare)], marked: false };
}

const WD = { 月: 0, 火: 1, 水: 2, 木: 3, 金: 4, 土: 5, 日: 6 };
const iso = (d) => d.toISOString().slice(0, 10);
const addDays = (d, n) => new Date(d.getTime() + n * 86400000);

// Resolve the date words of a note against the day it was sent (base = "yyyy-MM-dd"). Returns null if the words are not understood.
function resolveDate(words, base) {
  const w = nfkc(words).trim();
  const [by, bm, bd] = base.split('-').map(Number);
  const b = new Date(Date.UTC(by, bm - 1, bd));
  if (!w) return base;
  let m;
  if ((m = w.match(/(\d{4})[\/\-.年](\d{1,2})[\/\-.月](\d{1,2})/))) return iso(new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])));
  if ((m = w.match(/(\d{1,2})[\/月](\d{1,2})日?/))) {
    let d = new Date(Date.UTC(by, +m[1] - 1, +m[2]));
    if (d.getTime() - b.getTime() > 31 * 86400000) d = new Date(Date.UTC(by - 1, +m[1] - 1, +m[2]));
    return iso(d);
  }
  if (/一昨日|おととい/.test(w)) return iso(addDays(b, -2));
  if (/昨日|きのう/.test(w)) return iso(addDays(b, -1));
  if (/今日|本日|きょう/.test(w)) return base;
  if (/明日/.test(w)) return iso(addDays(b, 1));
  if ((m = w.match(/(\d+)日前/))) return iso(addDays(b, -Number(m[1])));
  if ((m = w.match(/(先週|今週)の?([月火水木金土日])/))) {
    const mondayIdx = (b.getUTCDay() + 6) % 7;
    const monday = addDays(b, -mondayIdx);
    return iso(addDays(monday, WD[m[2]] - (m[1] === '先週' ? 7 : 0)));
  }
  return null;
}

// A note that states an amount but produced no record is a silent miss. Report it instead of dropping it.
function checkNote(records, text) {
  if (!records.length && amountCandidates(text).marked) return ['an amount is written in the message, but no record was extracted'];
  return [];
}

// Check one extracted record against the message. Nothing is dropped: the caller records problems as "needs review".
function checkRecord(rec, text, categories, baseDate) {
  const problems = [];
  const src = squash(text);
  const cand = amountCandidates(text);
  const amount = Number(rec.amount);
  if (!Number.isFinite(amount) || amount === 0) problems.push('amount is missing');
  else if (!cand.values.includes(Math.abs(amount))) problems.push('amount ' + amount + ' is not written in the message');
  else if (!cand.marked) problems.push('the message has no 円 / yen next to the amount');
  if (rec.currency && rec.currency !== 'JPY') problems.push('currency is ' + rec.currency + ', not JPY');
  if (!rec.quote || !src.includes(squash(rec.quote))) problems.push('the quote is not in the message');
  const words = String(rec.date_text ?? '').trim();
  if (words && !src.includes(squash(words))) problems.push('the date words are not in the message');
  let date = resolveDate(words, baseDate);
  if (date === null) { problems.push('date "' + words + '" not understood (sent date used)'); date = baseDate; }
  if (rec.vendor && !src.includes(squash(rec.vendor))) problems.push('vendor is not in the message');
  const category = categories.includes(rec.category) ? rec.category : 'その他';
  if (!categories.includes(rec.category)) problems.push('category "' + rec.category + '" is not in the list');
  if (!['expense', 'income', 'other'].includes(rec.type)) problems.push('type is not expense / income / other');
  return { problems, date, category, amount: Math.abs(amount) || 0 };
}

const cats = String($('Config').first().json.categories).split(/\s*,\s*/).filter(Boolean);
const notes = $('Skip notes already recorded').all().map(i => i.json);
const TYPE_JA = { expense: '経費', income: '売上', other: 'その他' };
// The guard speaks English (it is easier to test); the sheet and the Chatwork reply are for Japanese readers.
const JA_RULES = [
  [/^an amount is written in the message, but no record was extracted/, '金額が書いてあるのに、記録を作れませんでした'],
  [/^no amount was found/, '金額が見つかりませんでした'],
  [/^the AI output could not be read/, 'AI の出力を読めませんでした'],
  [/^amount .* is not written in the message/, '金額が書き込みの中に見つかりません'],
  [/^amount is missing/, '金額がありません'],
  [/^the message has no 円/, '金額の横に「円」の表記がありません'],
  [/^currency is/, '日本円ではない通貨です'],
  [/^the quote is not in the message/, '金額の引用が書き込みに含まれていません'],
  [/^the date words are not in the message/, '日付の言葉が書き込みに含まれていません'],
  [/^date ".*" not understood/, '日付の言葉が分かりません（送信日を使いました）'],
  [/^vendor is not in the message/, '取引先名が書き込みにありません'],
  [/^category .* is not in the list/, '科目が一覧にありません（その他にしました）'],
  [/^type is not/, '種類（経費・売上）が分かりません'],
];
const ja = (list) => list.map(p => (JA_RULES.find(([re]) => re.test(p)) ?? [null, p])[1]).join('、');

const rows = [];
$input.all().forEach((it, i) => {
  const note = notes[i];
  let records = [];
  let problems0 = [];
  try {
    const rawText = it.json.content?.[0]?.text ?? it.json.text;
    // Claude has no JSON mode, so it may wrap the JSON in a code fence. Strip it before parsing.
    const t = String(rawText ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    records = JSON.parse(t).records ?? [];
  } catch (e) { problems0 = ['the AI output could not be read']; }
  const base = {
    message_id: note.message_id, room_id: note.room_id, room_name: note.room_name, sent_at: note.sent_at,
    sender_id: note.sender_id, sender_name: note.sender_name, text: note.text,
  };
  const noteProblems = problems0.length ? problems0 : checkNote(records, note.text);
  if (!records.length) {
    // nothing was extracted: say so in the sheet instead of dropping the note
    rows.push({ json: { ...base, record_id: note.message_id + '-1', type: '', amount: '', date: '', category: '', vendor: '', memo: '', quote: '',
      status: '要確認', problems: ja(noteProblems.length ? noteProblems : ['no amount was found in the message']) } });
    return;
  }
  records.forEach((r, k) => {
    const c = checkRecord(r, note.text, cats, note.sent_date);
    rows.push({ json: { ...base, record_id: note.message_id + '-' + (k + 1),
      type: TYPE_JA[r.type] ?? '', amount: Number(r.amount) < 0 ? -c.amount : c.amount, date: c.date, category: c.category,
      vendor: r.vendor ?? '', memo: r.memo ?? '', quote: r.quote ?? '',
      status: c.problems.length ? '要確認' : 'OK', problems: ja(c.problems) } });
  });
});
return rows;

const cfg = $('Config').first().json;
if (!cfg.reply_in_chatwork) return [];
const marker = String(cfg.reply_marker ?? '');

// one confirmation per note, even when the note produced several records
const byNote = new Map();
for (const it of $input.all()) {
  const r = it.json;
  if (!byNote.has(r.message_id)) byNote.set(r.message_id, []);
  byNote.get(r.message_id).push(r);
}
const yen = (n) => Number(n).toLocaleString('ja-JP') + '円';
const out = [];
for (const [messageId, rows] of byNote) {
  const first = rows[0];
  const lines = rows.map(r => {
    const what = r.amount === '' ? '(記録できませんでした)' : [r.type, yen(r.amount), r.category, r.date, r.memo ? '(' + r.memo + ')' : ''].filter(Boolean).join(' ');
    return (r.status === 'OK' ? '✅ ' : '⚠ 要確認: ') + what + (r.problems ? '\n   理由: ' + r.problems : '');
  });
  const body = '[rp aid=' + first.sender_id + ' to=' + first.room_id + '-' + messageId + ']' + marker + '\n' + lines.join('\n');
  out.push({ json: { room_id: first.room_id, message_id: messageId, body } });
}
return out;
